select m83_assert(not exists(select 1 from public.profile_synthesis_jobs where profile_id=m83_id('token-profile')),'missing synthesis quote rolls back enqueue');
insert into pt_state values('sq',public.prisma_tokens('quote',m83_id('a'),' {"functionName":"profile_synthesis","quantity":1}'));
select public.request_profile_synthesis(m83_id('a'),m83_id('token-person'),m83_id('token-profile'),(select (value->>'id')::uuid from pt_state where key='sq'));
select public.request_profile_synthesis(m83_id('a'),m83_id('token-person'),m83_id('token-profile'),(select (value->>'id')::uuid from pt_state where key='sq'));
select m83_assert((select count(*)=1 from private.prisma_synthesis_token_bindings where organization_id=m83_id('a')),'repeat synthesis request shares one reservation');
insert into pt_state values('sjob',public.claim_profile_synthesis(repeat('s',64)));
do $$ declare j jsonb; r jsonb; answers jsonb; begin
 select value into j from pt_state where key='sjob';
 select jsonb_agg(jsonb_build_object('questionId',x,'status','insufficient','statements','[]'::jsonb,'missingInformation',jsonb_build_array('Sem informação para este eixo.'))) into answers from unnest(array['trajectory','activities','contexts','competencies','results','education','objective','clarifications']) x;
 r:=jsonb_build_object('contractVersion','profile-synthesis-1.1.0','overview',jsonb_build_array(jsonb_build_object('text','Atuação financeira relatada.','nature','interpretation','sourceIds',jsonb_build_array(j#>>'{sources,0,id}'))),'answers',answers,'clarifications','[]'::jsonb,'issues','[]'::jsonb);
 perform m83_reject(format('select public.complete_profile_synthesis(%L,%L,%L,%L,''gpt-5.6-luna'',100,20,30)',repeat('s',64),j->>'id',gen_random_uuid(),r),'40001');
 perform public.complete_profile_synthesis(repeat('s',64),(j->>'id')::uuid,(j->>'lease')::uuid,r,'gpt-5.6-luna',100,20,30);
 perform m83_assert((select status='charged' and amount=5000 from private.prisma_token_reservations where operation_id=(select (value->>'id')::uuid from pt_state where key='sq')),'valid synthesis persists and debits exactly one operation');
 perform m83_assert(public.load_profile_synthesis(m83_id('a'),m83_id('token-person'))->>'state'='complete','persisted synthesis remains readable');
 perform public.request_profile_synthesis(m83_id('a'),m83_id('token-person'),m83_id('token-profile'),null);
 perform m83_assert((select count(*)=1 from private.prisma_token_reservations where function_name='profile_synthesis'),'stored synthesis reuse is free');
 update public.professional_profiles set profile_data=jsonb_set(profile_data,'{professionalObjective}','"Atuar com conciliação e controles"') where id=m83_id('token-profile');
 perform m83_assert(public.load_profile_synthesis(m83_id('a'),m83_id('token-person'))->>'state'='not_requested','new factual basis waits for explicit quoted action');
 insert into pt_state values('sqfail',public.prisma_tokens('quote',m83_id('a'),' {"functionName":"profile_synthesis","quantity":1}'));
 perform public.request_profile_synthesis(m83_id('a'),m83_id('token-person'),m83_id('token-profile'),(select (value->>'id')::uuid from pt_state where key='sqfail'));
 j:=public.claim_profile_synthesis(repeat('s',64));
 perform public.complete_profile_synthesis(repeat('s',64),(j->>'id')::uuid,(j->>'lease')::uuid,'{}','gpt-5.6-luna',100,20,30);
 perform m83_assert((select status='released' from private.prisma_token_reservations where operation_id=(select (value->>'id')::uuid from pt_state where key='sqfail')),'invalid synthesis releases credit while preserving previous result');
 perform m83_assert(public.load_profile_synthesis(m83_id('a'),m83_id('token-person'))->'previous'<>'null','failed new synthesis preserves prior analysis');
end $$;
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
select m83_assert(not (public.prisma_tokens('overview',m83_id('a'))::text like '%Synthetic owner%'),'operational commercial history excludes other actors');
select set_config('request.jwt.claim.sub',m83_id('super')::text,true);
select m83_assert(public.prisma_tokens('platform')->'technicalCosts' is not null,'only platform response includes technical cost aggregate');
-- Derived binding cascades; financial movements retain no Person FK/PII.
delete from public.people where id=m83_id('token-person');
select m83_assert(not exists(select 1 from private.prisma_synthesis_token_bindings where organization_id=m83_id('a')),'person erasure preserves existing cascade across derived binding');
